const check={};for(const k in S){const r=S[k].findAll(x=>x.reactions&&x.reactions.length>0).map(x=>x.name+'→'+x.reactions[0].actions[0].destinationId);if(S[k].reactions.length)r.unshift('FRAME→'+S[k].reactions[0].actions[0].destinationId);check[S[k].name+' '+S[k].id+' '+S[k].width+'x'+S[k].height]=r}
const fails=log.filter(x=>!x.startsWith('ok'));
const fonts=new Set();page.findAll(x=>x.type=='TEXT').forEach(t=>{if(t.fontName!==figma.mixed)fonts.add(t.fontName.family)});
return {fails,okCount:log.length-fails.length,check,fonts:[...fonts],flow:page.flowStartingPoints};

const page=await figma.getNodeByIdAsync('5:2');await figma.setCurrentPageAsync(page);
const r=page.findAll(x=>x.type=='TEXT'&&x.fontName!==figma.mixed&&x.fontName.family=='Inter').map(t=>t.name+'|'+t.parent.name);
const c={};r.forEach(k=>c[k]=(c[k]||0)+1);
// overflow audit: text wider than parent frame
const over=[];page.children.filter(f=>f.type=='FRAME').forEach(f=>{f.findAll(x=>x.type=='TEXT'&&x.visible).forEach(t=>{const a=t.absoluteBoundingBox,b=f.absoluteBoundingBox;if(a&&(a.x<b.x||a.x+a.width>b.x+b.width+0.5))over.push(f.name+':'+t.characters.slice(0,20))})});
return {c,over};

const page=await figma.getNodeByIdAsync('5:2');await figma.setCurrentPageAsync(page);
const fixed=[];for(const f of page.children.filter(c=>c.type=='FRAME'&&/^0[234]_/.test(c.name))){const bar=f.findOne(n=>n.name=='Bottom controls');const d=bar.children.find(c=>c.type=='INSTANCE'&&c.mainComponent.name.startsWith('Count='));d.layoutPositioning='ABSOLUTE';d.x=(bar.width-d.width)/2;d.y=(bar.height-d.height)/2;fixed.push(f.name+':'+d.x)}
const frames=page.children.filter(c=>c.type=='FRAME').map(c=>c.name+' '+c.id);
const refs={};for(const id of ['0:1','1:2','1:3','1:4']){const p=await figma.getNodeByIdAsync(id);refs[p.name]=p.children.map(c=>c.name+':'+c.children.length)}
return {fixed,count:frames.length,frames,refs,sectionKids:(await figma.getNodeByIdAsync('9:58')).children.length};
